css:
:root {
  color-scheme: light;
  --page: #f4f4f1;
  --panel: #ffffff;
  --panel-muted: #fafaf8;
  --ink: #1c1c19;
  --ink-2: #5e5e56;
  --ink-3: #73736a;
  --line: #e5e5df;
  --line-soft: #efefea;
  --line-strong: #d7d7cf;
  --focus: #2563eb;
  --radius: 10px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  background: var(--page);
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--page);
  color: var(--ink);
  font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 14px;
  line-height: 1.4;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

[hidden] {
  display: none !important;
}

::selection {
  background: #dfe7ff;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.topbar {
  background: var(--panel);
  border-bottom: 1px solid var(--line);
}

.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  width: 100%;
  max-width: 1120px;
  height: 56px;
  margin: 0 auto;
  padding: 0 32px;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  font-size: 13px;
  line-height: 1;
}

.breadcrumb-root {
  color: var(--ink-2);
  font-weight: 500;
  white-space: nowrap;
}

.breadcrumb-divider {
  color: #b6b6ae;
}

.breadcrumb-current {
  color: var(--ink);
  font-weight: 500;
  white-space: nowrap;
}

.context-tag {
  display: inline-flex;
  flex: none;
  align-items: center;
  height: 24px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--panel-muted);
  color: var(--ink-2);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.015em;
  white-space: nowrap;
}

.page {
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  padding: 32px 32px 48px;
}

.page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.page-head h1 {
  margin: 0;
  font-size: 27px;
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1.12;
}

.page-head p {
  margin: 7px 0 0;
  color: var(--ink-2);
  font-size: 13.5px;
  line-height: 1.45;
}

.head-count {
  flex: none;
  padding-bottom: 1px;
  color: var(--ink-2);
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.orders-panel {
  overflow: hidden;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 1px 2px rgba(25, 25, 21, 0.035);
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

.search-field {
  position: relative;
  flex: 1 1 280px;
  min-width: 0;
}

.search-field > svg {
  position: absolute;
  top: 50%;
  left: 11px;
  color: var(--ink-3);
  pointer-events: none;
  transform: translateY(-50%);
}

.search-field input {
  width: 100%;
  height: 36px;
  padding: 0 12px 0 34px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  outline: none;
  background: var(--panel);
  color: var(--ink);
  font-size: 13px;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.search-field input::placeholder {
  color: #74746b;
}

.search-field input:hover {
  border-color: #c6c6bd;
}

.search-field input:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
}

.search-field input::-webkit-search-cancel-button {
  -webkit-appearance: none;
  appearance: none;
}

.select-field {
  position: relative;
  flex: 0 0 158px;
}

.select-field select {
  width: 100%;
  height: 36px;
  padding: 0 31px 0 11px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  outline: none;
  appearance: none;
  -webkit-appearance: none;
  background: var(--panel);
  color: var(--ink);
  font-size: 13px;
  cursor: pointer;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.select-field select:hover {
  border-color: #c6c6bd;
}

.select-field select:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
}

.select-field > svg {
  position: absolute;
  top: 50%;
  right: 10px;
  color: var(--ink-2);
  pointer-events: none;
  transform: translateY(-50%);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 36px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: 6px;
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
}

.btn--primary {
  background: var(--ink);
  border-color: var(--ink);
  color: #ffffff;
}

.btn--primary:hover {
  background: #32322d;
  border-color: #32322d;
}

.btn--primary:active {
  background: #090908;
  border-color: #090908;
}

.btn--outline {
  background: var(--panel);
  border-color: var(--line-strong);
  color: var(--ink-2);
}

.btn--outline:hover {
  background: var(--panel-muted);
  border-color: #c4c4bb;
  color: var(--ink);
}

.btn--sm {
  height: 32px;
  padding: 0 10px;
  font-size: 12px;
}

.table-wrap {
  width: 100%;
}

.orders-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.orders-table th:nth-child(1) {
  width: 20%;
}

.orders-table th:nth-child(2) {
  width: 29%;
}

.orders-table th:nth-child(3) {
  width: 16%;
}

.orders-table th:nth-child(4) {
  width: 15%;
}

.orders-table th:nth-child(5) {
  width: 20%;
}

.orders-table thead th {
  height: 36px;
  padding: 0 20px;
  border-bottom: 1px solid var(--line);
  background: var(--panel-muted);
  color: var(--ink-3);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.07em;
  line-height: 1;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.orders-table thead th.num {
  text-align: right;
}

.orders-table tbody td {
  height: 54px;
  padding: 0 20px;
  border-bottom: 1px solid var(--line-soft);
  font-size: 13px;
  vertical-align: middle;
}

.orders-table tbody tr[data-status] {
  transition: background-color 100ms ease;
}

.orders-table tbody tr[data-status]:hover {
  background: #fbfbf8;
}

.orders-table tbody tr[data-status]:nth-child(6) td {
  border-bottom: 0;
}

.order-id {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 11.5px;
  font-weight: 500;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.customer-name {
  overflow: hidden;
  color: var(--ink);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 22px;
  padding: 0 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.status-dot {
  flex: none;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.8;
}

.status--paid {
  background: #eaf5ee;
  color: #14683f;
}

.status--pending {
  background: #fbf2de;
  color: #7a4b06;
}

.status--refunded {
  background: #faebeb;
  color: #913235;
}

.amount {
  color: var(--ink);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  text-align: right;
  white-space: nowrap;
}

.created {
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.no-results td {
  padding: 22px 20px;
  border-bottom: 1px solid var(--line-soft);
}

.no-results-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--ink-2);
  font-size: 13px;
  text-align: center;
}

.link-button {
  padding: 0;
  border: 0;
  background: none;
  color: var(--focus);
  font-size: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.link-button:hover {
  color: #1d4ed8;
}

.panel-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 48px;
  padding: 8px 16px 8px 20px;
  border-top: 1px solid var(--line);
  background: var(--panel);
}

.range {
  margin: 0;
  color: var(--ink-3);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 3px;
}

.page-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 28px;
  height: 28px;
  padding: 0 7px;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: var(--ink-2);
  font-size: 12px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
}

.page-btn:hover:not(:disabled) {
  background: #f1f1ed;
  color: var(--ink);
}

.page-btn[aria-current="page"] {
  background: var(--ink);
  border-color: var(--ink);
  color: #ffffff;
}

.page-btn--nav {
  border-color: var(--line);
  background: var(--panel);
}

.page-btn--nav:hover:not(:disabled) {
  border-color: var(--line-strong);
  background: var(--panel-muted);
}

.page-btn:disabled {
  color: #a1a198;
  cursor: not-allowed;
}

.empty-section {
  margin-top: 28px;
}

.section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 4px 20px;
  margin-bottom: 10px;
  padding: 0 2px;
}

.section-head h2 {
  margin: 0;
  color: var(--ink);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.section-head p {
  margin: 0;
  color: var(--ink-3);
  font-size: 12px;
}

.empty-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px;
  border: 1px dashed #d3d3ca;
  border-radius: var(--radius);
  background: #fbfbf9;
}

.empty-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--ink-3);
}

.empty-copy {
  flex: 1 1 auto;
  min-width: 0;
}

.empty-copy h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.empty-copy p {
  margin: 4px 0 0;
  color: var(--ink-2);
  font-size: 12.5px;
  line-height: 1.5;
}

.empty-card .btn {
  flex: none;
}

@media (max-width: 720px) {
  .topbar-inner {
    height: 52px;
    gap: 12px;
    padding: 0 16px;
  }

  .breadcrumb {
    gap: 7px;
    font-size: 12.5px;
  }

  .context-tag {
    height: 22px;
    padding: 0 7px;
    font-size: 10.5px;
  }

  .page {
    padding: 24px 16px 40px;
  }

  .page-head {
    align-items: flex-start;
    gap: 14px;
    margin-bottom: 18px;
  }

  .page-head h1 {
    font-size: 24px;
  }

  .page-head p {
    max-width: 270px;
    margin-top: 6px;
    font-size: 13px;
  }

  .head-count {
    padding-top: 4px;
    font-size: 12px;
  }

  .toolbar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px;
    padding: 12px;
  }

  .search-field {
    grid-column: 1 / -1;
  }

  .search-field > svg {
    left: 12px;
  }

  .search-field input {
    height: 42px;
    padding-left: 36px;
    font-size: 16px;
  }

  .select-field {
    width: 100%;
    min-width: 0;
    flex: none;
  }

  .select-field select {
    height: 42px;
    padding-left: 12px;
    font-size: 14px;
  }

  .btn {
    height: 42px;
  }

  .orders-table,
  .orders-table tbody {
    display: block;
    width: 100%;
  }

  .orders-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .orders-table tbody tr[data-status] {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    grid-template-areas:
      "order created status"
      "customer customer amount";
    align-items: center;
    gap: 4px 12px;
    padding: 12px 16px;
    border-bottom: 1px solid var(--line-soft);
  }

  .orders-table tbody tr[data-status]:nth-child(6) {
    border-bottom: 0;
  }

  .orders-table tbody td {
    width: auto;
    height: auto;
    padding: 0;
    border: 0;
  }

  .orders-table tbody td[data-label="Order"] {
    grid-area: order;
  }

  .orders-table tbody td[data-label="Created"] {
    grid-area: created;
    justify-self: start;
    color: var(--ink-3);
    font-size: 11.5px;
  }

  .orders-table tbody td[data-label="Created"]::before {
    content: "·";
    margin-right: 7px;
    color: #bfbfb6;
  }

  .orders-table tbody td[data-label="Status"] {
    grid-area: status;
    justify-self: end;
  }

  .orders-table tbody td[data-label="Customer"] {
    grid-area: customer;
    min-width: 0;
  }

  .orders-table tbody td[data-label="Amount"] {
    grid-area: amount;
    justify-self: end;
    font-size: 13px;
  }

  .order-id {
    font-size: 11px;
  }

  .customer-name {
    font-size: 13.5px;
  }

  .status {
    height: 22px;
    padding: 0 7px;
  }

  .no-results {
    display: block;
  }

  .no-results td {
    display: block;
    padding: 20px 16px;
    border-bottom: 1px solid var(--line-soft);
  }

  .panel-footer {
    min-height: 48px;
    padding: 6px 12px;
  }

  .range {
    font-size: 11.5px;
  }

  .page-btn {
    min-width: 34px;
    height: 34px;
    padding: 0;
  }

  .page-btn--nav {
    width: 34px;
  }

  .page-label {
    display: none;
  }

  .empty-section {
    margin-top: 26px;
  }

  .section-head {
    display: block;
    margin-bottom: 10px;
  }

  .section-head p {
    margin-top: 3px;
    line-height: 1.45;
  }

  .empty-card {
    flex-direction: column;
    gap: 12px;
    padding: 28px 20px;
    text-align: center;
  }

  .empty-copy {
    flex: none;
    width: 100%;
  }

  .empty-copy p {
    max-width: 280px;
    margin: 4px auto 0;
  }

  .empty-card .btn {
    margin-top: 4px;
  }
}

@media (max-width: 380px) {
  .page-head p {
    max-width: 230px;
  }

  .panel-footer {
    justify-content: center;
  }

  .range {
    width: 100%;
    text-align: center;
  }

  .pagination {
    margin: 0 auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}
